import os, re, json

d = os.environ['RLM_SESSION_DIR']
session_name = os.path.basename(d)
t = open(d + '/../../sessions/' + session_name + '.jsonl').read()

G = {}

# Find all grid blocks
# Pattern: Test input or Demo pair with dimensions, followed by h*w lines of grid data
grid_pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):', re.MULTILINE)

pos = 0
for m in grid_pattern.finditer(t):
    label = m.group(1).split(' ')[0]
    h, w = int(m.group(2)), int(m.group(3))
    start = m.end()

    # Get the next h lines of grid data (they contain only digits and spaces)
    grid_lines = []
    for i in range(start, len(t)):
        # Look for patterns that look like a row (only digits 0-9 and spaces)
        line = t[i:i+max(15, w)]
        if re.match(r'^[0-9 ]+$', line.strip()) and len(line.split()) <= w:
            row = [int(x) for x in line.split()]
            if row:
                grid_lines.append(row)
                if len(grid_lines) == h:
                    break
        if 'Wrong attempts' in line or 'Reply with' in line:
            break

    if label not in G:
        G[label] = grid_lines
    else:
        G[label].extend(grid_lines[:h])

print(f"Found {len(G)} grids")
for k, v in G.items():
    print(f"{k}: {len(v)}x{len(v[0]) if v else 0}")
    for i, row in enumerate(v[:3]):
        print(f"  Row {i}: {row}")
    if len(v) > 3:
        print(f"  ... and {len(v)-3} more rows")

